	}
	if mintPriceUgnot < 0 {
		panic("nft: mintPrice")
	}
	putCollection(cur, caller, slug, name, cover, maxSupply, mintPriceUgnot, true)
	chain.Emit("CreateDrop", "slug", slug)
	record("drop", slug, caller.String(), name, 0, mintPriceUgnot)
}

