func TokensOf(owner address) string {
	out := ""
	items.Iterate("", "", func(_ string, value any) bool {
		it := value.(*item)
		if it.owner != owner {
			return false
		}
		if out != "" {
			out += ","
		}
		out += strconv.Itoa(it.id)
		return false
	})
	return out
}

func requireInit() {
	if !inited {
		panic("nft: call Init first")
	}
}

func requireUser(cur realm) address {
	requireInit()
	if !cur.IsCurrent() {
		panic("nft: spoofed realm")
	}
	if !cur.Previous().IsUserCall() {
		panic("nft: EOA only")
	}
	return cur.Previous().Address()
}

func requireCreator(cur realm, slug string) (address, *collection) {
	caller := requireUser(cur)
	col := mustCollection(slug)
	if col.creator != caller {
		panic("nft: not creator")
	}
	return caller, col
}

func putCollection(cur realm, caller address, slug, name, cover string, maxSupply int, mintPrice int64, drop bool) {
	if !validSlug(slug) {
		panic("nft: slug")
	}
	if !validName(name) {
		panic("nft: name")
	}
	if !validImage(cover) {
		panic("nft: cover")
	}
	if collections.Has(slug) {
		panic("nft: collection exists")
	}
	col := &collection{
		slug:      slug,
		name:      name,
		cover:     cover,
		creator:   caller,
		maxSupply: maxSupply,
		mintPrice: mintPrice,
		drop:      drop,
	}
	attachToken(cur, col)
	collections.Set(slug, col)
}

func attachToken(cur realm, col *collection) {
	if !cur.IsCurrent() {
		panic("nft: spoofed realm")
	}
	sym := col.slug
	if len(sym) < 1 || len(sym) > grc721.MaxSymbolLen {
		panic("nft: symbol")
	}
	if symbols.Has(sym) {
		panic("nft: symbol exists")
	}
	tok, led := grc721.NewToken(col.name, sym, tokenSeq.Next(), cur)
	col.token = tok
	col.ledger = led
	col.symbol = sym
	symbols.Set(sym, col.slug)
}

func itemTid(id int) grc721.TokenID {
	return grc721.TokenID(strconv.Itoa(id))
}

func mustLedger(slug string) *grc721.PrivateLedger {
	col := mustCollection(slug)
	if col.ledger == nil {
		panic("nft: no ledger")
	}
	return col.ledger
}

func grcMint(slug string, to address, id int) {
	err := mustLedger(slug).Mint(to, itemTid(id))
	if err != nil {
		panic("nft: mint")
	}
}

func grcTransfer(slug string, spender, from, to address, id int) {
	err := mustLedger(slug).TransferFrom(spender, from, to, itemTid(id))
	if err != nil {
		panic("nft: transfer")
	}
}

func slotCap(col *collection) int {
	if col.maxSupply > 0 {
		return col.maxSupply
	}
	return dropSlotHardCap
}

func collectionLine(col *collection) string {
	return col.slug + "|" + col.name + "|" + col.cover + "|" + strconv.Itoa(col.count) + "|" + strconv.FormatInt(col.mintPrice, 10) + "|" + strconv.Itoa(col.maxSupply) + "|" + strconv.Itoa(col.minted) + "|" + col.creator.String() + "|" + strconv.FormatBool(col.paused) + "|" + strconv.FormatBool(col.drop) + "|" + col.bio
}

func mintTo(caller address, slug, name, imageURL string) int {
	if !validName(name) {
		panic("nft: name")
	}
	if !validImage(imageURL) {
		panic("nft: image")
	}
	col := mustCollection(slug)
	nextID++
	id := nextID
	it := &item{
		id:         id,
		name:       name,
		image:      imageURL,
		revealed:   true,
		slot:       -1,
		owner:      caller,
		rarity:     rarityOf(id),
		collection: slug,
	}
	items.Set(itemKey(id), it)
	grcMint(slug, caller, id)
	col.count++
	collections.Set(slug, col)
	chain.Emit("Mint", "id", strconv.Itoa(id), "owner", caller.String(), "collection", slug)
	record("mint", slug, caller.String(), name, id, 0)
	return id
}

func record(kind, slug, actor, name string, id int, price int64) {
	key := actSeq.Next().String()
	acts.Set(key, &act{
		kind:  kind,
		id:    id,
		slug:  slug,
		actor: actor,
		name:  name,
		price: price,
	})
	if acts.Size() > 50 {
		old, _ := acts.GetByIndex(0)
		acts.Remove(old)
	}
}

func activityLines(slug string) string {
	out := ""
	n := 0
	acts.ReverseIterate("", "", func(_ string, value any) bool {
		a := value.(*act)
		if slug != "" && a.slug != slug {
			return false
		}
		if n >= 50 {
			return true
		}
		if out != "" {
			out += "\n"
		}
		out += a.kind + "|" + strconv.Itoa(a.id) + "|" + a.slug + "|" + a.actor + "|" + strconv.FormatInt(a.price, 10) + "|" + a.name
		n++
		return false
	})
	return out
}

func saleTape(slug string, id int, byID bool) string {
	out := ""
	n := 0
	acts.ReverseIterate("", "", func(_ string, value any) bool {
		a := value.(*act)
		if !saleTapeKind(a) {
			return false
		}
		if slug != "" && a.slug != slug {
			return false
		}
		if byID && a.id != id {
			return false
		}
		if n >= 50 {
			return true
		}
		if out != "" {
			out += "\n"
		}
		out += a.kind + "|" + strconv.Itoa(a.id) + "|" + strconv.FormatInt(a.price, 10) + "|" + a.name
		n++
		return false
	})
	return out
}

func saleTapeKind(a *act) bool {
	if a.kind == "buy" {
		return true
	}
	return a.kind == "list" && a.price > 0
}

func mustItem(id int) *item {
	v := items.Get(itemKey(id))
	if v == nil {
		panic("nft: unknown item")
	}
	return v.(*item)
}

func mustCollection(slug string) *collection {
	v := collections.Get(slug)
	if v == nil {
		panic("nft: unknown collection")
	}
	return v.(*collection)
}

func itemKey(id int) string {
	return strconv.Itoa(id)
}

// rarityOf is deterministic from id (not RNG). 1 Common, 2 Uncommon, 3 Rare, 4 Epic, 0 Legendary.
func rarityOf(id int) string {
	r := id % 10
	if r == 0 {
		return "Legendary"
	}
	if r == 1 {
		return "Common"
	}
	if r == 2 {
		return "Uncommon"
	}
	if r == 3 {
		return "Rare"
	}
	if r == 4 {
		return "Epic"
	}
	if r <= 7 {
		return "Uncommon"
	}
	return "Common"
}

func setRarity(id int, rarity string) {
	it := mustItem(id)
	it.rarity = rarity
	items.Set(itemKey(id), it)
}

func hideMint(id, slotIndex int, cover string) {
	it := mustItem(id)
	it.name = "Unrevealed"
	it.image = cover
	it.rarity = ""
	it.traits = ""
	it.revealed = false
	it.slot = slotIndex
	items.Set(itemKey(id), it)
}

func applySlot(id int, s *dropSlot) {
	it := mustItem(id)
	it.name = s.name
	it.image = s.image
	if s.rarity != "" {
		it.rarity = s.rarity
	}
	it.traits = s.traits
	it.revealed = true
	items.Set(itemKey(id), it)
}

func validRarity(s string) bool {
	if s == "" {
		return true
	}
	return s == "Common" || s == "Uncommon" || s == "Rare" || s == "Epic" || s == "Legendary"
}

func validTraits(s string) bool {
	if s == "" {
		return true
	}
	if len(s) > 200 {
		return false
	}
	if strings.ContainsAny(s, "\n\r|") {
		return false
	}
	n := 0
	for _, part := range strings.Split(s, ";") {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		colon := strings.Index(part, ":")
		if colon <= 0 || colon >= len(part)-1 {
			return false
		}
		key := strings.TrimSpace(part[:colon])
		val := strings.TrimSpace(part[colon+1:])
		if key == "" || val == "" {
			return false
		}
		if !asciiSet(key, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 _-") {
			return false
		}
		if !asciiSet(val, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 _-") {
			return false
		}
		n++
		if n > 8 {
			return false
		}
	}
	return n >= 1
}

func validName(name string) bool {
	if len(name) < 1 || len(name) > maxNameLen {
		return false
	}
	return !strings.ContainsAny(name, "\n\r|")
}

func validBio(bio string) bool {
	if len(bio) > maxBioLen {
		return false
	}
	return !strings.ContainsAny(bio, "\n\r|")
}

func validSocial(s string) bool {
	if s == "" {
		return true
	}
	if len(s) > 120 {
		return false
	}
	if strings.ContainsAny(s, " \t\n\r|<>\"'`") {
		return false
	}
	if strings.HasPrefix(s, "https://") || strings.HasPrefix(s, "http://") || strings.HasPrefix(s, "@") {
		return true
	}
	return asciiSet(s, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._-")
}

func validSlug(s string) bool {
	if len(s) < 2 || len(s) > 16 {
		return false
	}
	return asciiSet(s, "abcdefghijklmnopqrstuvwxyz0123456789-")
}

func validImage(u string) bool {
	if u == "" {
		return true
	}
	if len(u) > maxImageLen {
		return false
	}
	if strings.ContainsAny(u, " \t\n\r|<>\"'`") {
		return false
	}
	if strings.HasPrefix(u, "https://") || strings.HasPrefix(u, "http://") {
		return true
	}
	// local demo files under web/public/samples/
	const prefix = "/samples/"
	if !strings.HasPrefix(u, prefix) {
		return false
	}
	rest := u[len(prefix):]
	if rest == "" {
		return false
	}
	return asciiSet(rest, "abcdefghijklmnopqrstuvwxyz0123456789._-")
}

func asciiSet(s, allowed string) bool {
	for i := 0; i < len(s); i++ {
		if !strings.ContainsRune(allowed, rune(s[i])) {
			return false
		}
	}
	return true
}

package nftv6

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/g1n4pl5uc4yt5r96m9w6fmdznx3x0jyg8l6arhmt/bazaar/fee/v1"
)

type offerRec struct {
	bidder address
	amount int64
}

func offerKey(id int, bidder address) string {
	return strconv.Itoa(id) + ":" + bidder.String()
}

func Offer(cur realm, id int) {
	caller := requireUser(cur)
	it := mustItem(id)
	sent := unsafe.OriginSend().AmountOf(nativeDenom)
	if sent <= 0 {
		panic("nft: offer")
	}
	if caller == it.seller || caller == it.owner {
		panic("nft: self offer")
	}
	key := offerKey(id, caller)
	prev := offers.Get(key)
	if prev != nil {
		old := prev.(*offerRec)
		bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		bk.SendCoins(self, caller, chain.Coins{{Denom: nativeDenom, Amount: old.amount}})
	}
	offers.Set(key, &offerRec{bidder: caller, amount: sent})
	chain.Emit("Offer", "id", strconv.Itoa(id), "bidder", caller.String(), "amount", strconv.FormatInt(sent, 10))
	record("offer", it.collection, caller.String(), it.name, id, sent)
}

func CancelOffer(cur realm, id int) {
	caller := requireUser(cur)
	key := offerKey(id, caller)
	v := offers.Get(key)
	if v == nil {
		panic("nft: no offer")
	}
	rec := v.(*offerRec)
	offers.Remove(key)
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bk.SendCoins(self, caller, chain.Coins{{Denom: nativeDenom, Amount: rec.amount}})
	it := mustItem(id)
	chain.Emit("CancelOffer", "id", strconv.Itoa(id), "bidder", caller.String())
	record("canceloffer", it.collection, caller.String(), it.name, id, rec.amount)
}

func AcceptOffer(cur realm, id int, bidder address) {
	caller := requireUser(cur)
	it := mustItem(id)
	if it.listed {
		if caller != it.seller {
			panic("nft: not seller")
		}
	} else if caller != it.owner {
		panic("nft: not owner")
	}
	key := offerKey(id, bidder)
	v := offers.Get(key)
	if v == nil {
		panic("nft: no offer")
	}
	rec := v.(*offerRec)
	amt := rec.amount
	offers.Remove(key)
	proto := fee.ProtocolFee(amt, protocolBps)
	royal := int64(0)
	cv := collections.Get(it.collection)
	if cv != nil {
		c := cv.(*collection)
		if c.royaltyBps > 0 {
			royal = fee.ProtocolFee(amt, int64(c.royaltyBps))
		}
	}
	if proto+royal > amt {
		panic("nft: fee")
	}
	pay := amt - proto - royal
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	if pay > 0 {
		bk.SendCoins(self, caller, chain.Coins{{Denom: nativeDenom, Amount: pay}})
	}
	if royal > 0 && cv != nil {
		c := cv.(*collection)
		if c.creator.String() != "" {
			bk.SendCoins(self, c.creator, chain.Coins{{Denom: nativeDenom, Amount: royal}})
		}
	}
	fees += proto
	from := caller
	if it.listed {
		from = self
	}
	grcTransfer(it.collection, from, from, bidder, id)
	it.listed = false
	it.seller = address("")
	it.price = 0
	it.owner = bidder
	items.Set(itemKey(id), it)
	chain.Emit("AcceptOffer", "id", strconv.Itoa(id), "bidder", bidder.String(), "amount", strconv.FormatInt(amt, 10))
	record("accept", it.collection, bidder.String(), it.name, id, amt)
}

func InstantSell(cur realm, id int) {
	bidder, _, ok := topOfferOf(id)
	if !ok {
		panic("nft: no offer")
	}
	AcceptOffer(cur, id, bidder)
}

func topOfferOf(id int) (address, int64, bool) {
	prefix := strconv.Itoa(id) + ":"
	found := false
	var best address
	bestAmt := int64(0)
	offers.Iterate("", "", func(key string, value any) bool {
		if !strings.HasPrefix(key, prefix) {
			return false
		}
		rec := value.(*offerRec)
		if !found || rec.amount > bestAmt {
			found = true
			best = rec.bidder
			bestAmt = rec.amount
		}
		return false
	})
	return best, bestAmt, found
}

func ListOffers(slug string) string {
	mustCollection(slug)
	out := ""
	offers.Iterate("", "", func(key string, value any) bool {
		rec := value.(*offerRec)
		id := 0
		colon := -1
		for i := 0; i < len(key); i++ {
			if key[i] == ':' {
				colon = i
				break
			}
		}
		if colon <= 0 {
			return false
		}
		id, _ = strconv.Atoi(key[:colon])
		it := mustItem(id)
		if it.collection != slug {
			return false
		}
		if out != "" {
			out += "\n"
		}
		out += strconv.Itoa(id) + "|" + rec.bidder.String() + "|" + strconv.FormatInt(rec.amount, 10) + "|" + it.name
		return false
	})
	return out
}

func CollectionTopOffer(slug string) int64 {
	top := int64(0)
	raw := ListOffers(slug)
	if raw == "" {
		return 0
	}
	lines := strings.Split(raw, "\n")
	for _, line := range lines {
		parts := strings.Split(line, "|")
		if len(parts) < 3 {
			continue
		}
		amt, _ := strconv.ParseInt(parts[2], 10, 64)
		if amt > top {
			top = amt
		}
	}
	return top
}

package nftv6

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
)

type pool struct {
	gnot   int64
	shares int64
	nfts   int
}

func poolPosKey(slug string, who address) string {
	return slug + ":" + who.String()
}

func DepositPool(cur realm, slug string) {
	caller := requireUser(cur)
	mustCollection(slug)
	sent := unsafe.OriginSend().AmountOf(nativeDenom)
	if sent <= 0 {
		panic("nft: pool deposit")
	}
	p := getPool(slug)
	add := sent
	if p.shares > 0 && p.gnot > 0 {
		add = sent * p.shares / p.gnot
		if add <= 0 {
			add = 1
		}
	}
	p.gnot += sent
	p.shares += add
	pools.Set(slug, p)
	pk := poolPosKey(slug, caller)
	have := int64(0)
	if v := lpPos.Get(pk); v != nil {
		have = v.(int64)
	}
	lpPos.Set(pk, have+add)
	chain.Emit("DepositPool", "slug", slug, "amount", strconv.FormatInt(sent, 10))
	record("depositpool", slug, caller.String(), slug, 0, sent)
}

func WithdrawPool(cur realm, slug string, shares int64) {
	caller := requireUser(cur)
	if shares <= 0 {
		panic("nft: shares")
	}
	p := getPool(slug)
	pk := poolPosKey(slug, caller)
	have := int64(0)
	if v := lpPos.Get(pk); v != nil {
		have = v.(int64)
	}
	if shares > have {
		panic("nft: shares")
	}
	if p.shares <= 0 {
		panic("nft: empty pool")
	}
	out := p.gnot * shares / p.shares
	p.gnot -= out
	p.shares -= shares
	pools.Set(slug, p)
	left := have - shares
	if left <= 0 {
		lpPos.Remove(pk)
	} else {
		lpPos.Set(pk, left)
	}
	if out > 0 {
		bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		bk.SendCoins(self, caller, chain.Coins{{Denom: nativeDenom, Amount: out}})
	}
	chain.Emit("WithdrawPool", "slug", slug, "shares", strconv.FormatInt(shares, 10))
	record("withdrawpool", slug, caller.String(), slug, 0, out)
}

func DepositNftPool(cur realm, id int) {
	caller := requireUser(cur)
	it := mustItem(id)
	if it.listed {
		panic("nft: listed")
	}
	if it.owner != caller {
		panic("nft: not owner")
	}
	grcTransfer(it.collection, caller, caller, self, id)
	it.owner = self
	items.Set(itemKey(id), it)
	nftPos.Set(itemKey(id), caller)
	p := getPool(it.collection)
	p.nfts++
	pools.Set(it.collection, p)
	chain.Emit("DepositNftPool", "id", strconv.Itoa(id), "slug", it.collection)
	record("depositnft", it.collection, caller.String(), it.name, id, 0)
}

func WithdrawNftPool(cur realm, id int) {
	caller := requireUser(cur)
	it := mustItem(id)
	v := nftPos.Get(itemKey(id))
	if v == nil {
		panic("nft: not in pool")
	}
	who := v.(address)
	if who != caller {
		panic("nft: not depositor")
	}
	if it.owner != self || it.listed {
		panic("nft: not in pool")
	}
	grcTransfer(it.collection, self, self, caller, id)
	it.owner = caller
	items.Set(itemKey(id), it)
	nftPos.Remove(itemKey(id))
	p := getPool(it.collection)
	if p.nfts > 0 {
		p.nfts--
	}
	pools.Set(it.collection, p)
	chain.Emit("WithdrawNftPool", "id", strconv.Itoa(id), "slug", it.collection)
	record("withdrawnft", it.collection, caller.String(), it.name, id, 0)
}

func ListPoolNfts(slug string) string {
	mustCollection(slug)
	out := ""
	nftPos.Iterate("", "", func(key string, value any) bool {
		id, err := strconv.Atoi(key)
		if err != nil {
			return false
		}
		it := mustItem(id)
		if it.collection != slug {
			return false
		}
		who := value.(address)
		if out != "" {
			out += "\n"
		}
		out += strconv.Itoa(id) + "|" + it.name + "|" + who.String()
		return false
	})
	return out
}

func PoolOf(slug string) string {
	mustCollection(slug)
	p := getPool(slug)
	return strconv.FormatInt(p.gnot, 10) + "|" + strconv.FormatInt(p.shares, 10) + "|" + strconv.Itoa(p.nfts)
}

func MyPoolShares(slug, who string) int64 {
	v := lpPos.Get(slug + ":" + who)
	if v == nil {
		return 0
	}
	return v.(int64)
}

func getPool(slug string) *pool {
	v := pools.Get(slug)
	if v != nil {
		return v.(*pool)
	}
	return &pool{}
}

package nftv7

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/g1n4pl5uc4yt5r96m9w6fmdznx3x0jyg8l6arhmt/bazaar/fee/v1"
)

const sweepCap = 10

const (
	protocolBps = int64(50)
	nativeDenom = "ugnot"
)

func takeLaunchFee() {
	sent := unsafe.OriginSend()
	if len(sent) > 1 {
		panic("nft: extra denoms")
	}
	if sent.AmountOf(nativeDenom) != launchFee {
		panic("nft: launch fee")
	}
	fees += launchFee
}

func PublicMint(cur realm, slug string) int {
	caller := requireUser(cur)
	col := mustCollection(slug)
	if !col.drop {
		panic("nft: not a drop")
	}
	if col.paused {
		panic("nft: paused")
	}
	if col.maxSupply > 0 && col.minted >= col.maxSupply {
		panic("nft: sold out")
	}
	requireAllow(slug, caller)
	checkMintCap(slug, caller)
	pay := col.mintPrice
	if col.wlSupply > 0 && col.minted < col.wlSupply {
		pay = col.wlPrice
	}
	sent := unsafe.OriginSend()
	if len(sent) > 1 {
		panic("nft: extra denoms")
	}
	if sent.AmountOf(nativeDenom) != pay {
		panic("nft: wrong payment")
	}
	n := col.minted + 1
	name := col.name + " #" + strconv.Itoa(n)
	image := "/samples/" + slug + "-0" + strconv.Itoa(n) + ".png"
	if !validImage(image) {
		image = col.cover
	}
	var slot *dropSlot
	if col.loaded > 0 {
		if col.minted >= col.loaded {
			panic("nft: no slot")
		}
		v := dropSlots.Get(slotKey(slug, col.minted))
		if v == nil {
			panic("nft: no slot")
		}
		slot = v.(*dropSlot)
		name = slot.name
		image = slot.image
	}
	mintName := name
	mintImage := image
	if slot != nil && col.hidden {
		mintName = "Unrevealed"
		mintImage = col.cover
	}
	id := mintTo(caller, slug, mintName, mintImage)
	if slot != nil {
		if col.hidden {
			hideMint(id, col.minted, col.cover)
		} else {
			applySlot(id, slot)
		}
	}
	col.minted++
	collections.Set(slug, col)
	noteMint(slug, caller)
	if pay > 0 {
		bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		bk.SendCoins(self, col.creator, chain.Coins{{Denom: nativeDenom, Amount: pay}})
	}
	chain.Emit("PublicMint", "id", strconv.Itoa(id), "slug", slug, "n", strconv.Itoa(n))
	record("publicmint", slug, caller.String(), mintName, id, pay)
	return id
}

func List(cur realm, id int, priceUgnot int64) {
	caller := requireUser(cur)
	if priceUgnot <= 0 {
		panic("nft: price")
	}
	it := mustItem(id)
	if it.listed {
		panic("nft: listed")
	}
	if it.owner != caller {
		panic("nft: not owner")
	}
	grcTransfer(it.collection, caller, caller, self, id)
	it.listed = true
	it.seller = caller
	it.price = priceUgnot
	it.owner = self
	items.Set(itemKey(id), it)
	chain.Emit("List", "id", strconv.Itoa(id), "seller", caller.String(), "price", strconv.FormatInt(priceUgnot, 10))
	record("list", it.collection, caller.String(), it.name, id, priceUgnot)
}

func UpdatePrice(cur realm, id int, priceUgnot int64) {
	caller := requireUser(cur)
	if priceUgnot <= 0 {
		panic("nft: price")
	}
	it := mustItem(id)
	if !it.listed {
		panic("nft: not listed")
	}
	if it.seller != caller {
		panic("nft: not seller")
	}
	it.price = priceUgnot
	items.Set(itemKey(id), it)
	chain.Emit("List", "id", strconv.Itoa(id), "seller", caller.String(), "price", strconv.FormatInt(priceUgnot, 10))
	record("list", it.collection, caller.String(), it.name, id, priceUgnot)
}

func Buy(cur realm, id int) {
	caller := requireUser(cur)
	it := mustItem(id)
	if !it.listed {
		panic("nft: not listed")
	}
	sent := unsafe.OriginSend().AmountOf(nativeDenom)
	if sent != it.price {
		panic("nft: wrong payment")
	}
	fillBuy(cur, caller, id)
}

func Sweep(cur realm, ids string) {
	caller := requireUser(cur)
	parsed := parseIdList(ids)
	if len(parsed) < 1 || len(parsed) > sweepCap {
		panic("nft: sweep")
	}
	total := int64(0)
	for i, id := range parsed {
		for j := 0; j < i; j++ {
			if parsed[j] == id {
				panic("nft: sweep")
			}
		}
		it := mustItem(id)
		if !it.listed {
			panic("nft: not listed")
		}
		if caller == it.seller {
			panic("nft: self buy")
		}
		if it.price <= 0 {
			panic("nft: price")
		}
		total += it.price
	}
	sent := unsafe.OriginSend().AmountOf(nativeDenom)
	if sent != total {
		panic("nft: wrong payment")
	}
	for _, id := range parsed {
		fillBuy(cur, caller, id)
	}
	chain.Emit("Sweep", "n", strconv.Itoa(len(parsed)), "amount", strconv.FormatInt(total, 10))
}

func fillBuy(cur realm, buyer address, id int) {
	it := mustItem(id)
	if !it.listed {
		panic("nft: not listed")
	}
	if buyer == it.seller {
		panic("nft: self buy")
	}
	price := it.price
	proto := fee.ProtocolFee(price, protocolBps)
	royal := int64(0)
	cv := collections.Get(it.collection)
	if cv != nil {
		c := cv.(*collection)
		if c.royaltyBps > 0 {
			royal = fee.ProtocolFee(price, int64(c.royaltyBps))
		}
	}
	if proto+royal > price {
		panic("nft: fee")
	}
	sellerAmt := price - proto - royal
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	if sellerAmt > 0 {
		bk.SendCoins(self, it.seller, chain.Coins{{Denom: nativeDenom, Amount: sellerAmt}})
	}
	if royal > 0 && cv != nil {
		c := cv.(*collection)
		if c.creator.String() != "" {
			bk.SendCoins(self, c.creator, chain.Coins{{Denom: nativeDenom, Amount: royal}})
		}
	}
	fees += proto
	grcTransfer(it.collection, self, self, buyer, id)
	it.listed = false
	it.owner = buyer
	it.seller = address("")
	it.price = 0
	items.Set(itemKey(id), it)
	chain.Emit("Buy", "id", strconv.Itoa(id), "buyer", buyer.String(), "fee", strconv.FormatInt(proto, 10))
	record("buy", it.collection, buyer.String(), it.name, id, price)
}

func parseIdList(s string) []int {
	if s == "" {
		return nil
	}
	parts := strings.Split(s, ",")
	out := make([]int, 0, len(parts))
	for _, p := range parts {
		p = strings.TrimSpace(p)
		if p == "" {
			panic("nft: sweep")
		}
		id, err := strconv.Atoi(p)
		if err != nil || id <= 0 {
			panic("nft: sweep")
		}
		out = append(out, id)
	}
	return out
}

func Cancel(cur realm, id int) {
	caller := requireUser(cur)
	it := mustItem(id)
	if !it.listed {
		panic("nft: not listed")
	}
	if caller != it.seller {
		panic("nft: not seller")
	}
	grcTransfer(it.collection, self, self, it.seller, id)
	it.listed = false
	it.owner = it.seller
	it.seller = address("")
	it.price = 0
	items.Set(itemKey(id), it)
	chain.Emit("Cancel", "id", strconv.Itoa(id))
	record("cancel", it.collection, caller.String(), it.name, id, 0)
}

func TransferAdmin(cur realm, next address) {
	caller := requireUser(cur)
	if caller != admin {
		panic("nft: not admin")
	}
	if !next.IsValid() {
		panic("nft: invalid address")
	}
	if next == admin {
		panic("nft: already admin")
	}
	admin = next
	chain.Emit("TransferAdmin", "addr", next.String())
}

func WithdrawFees(cur realm) {
	caller := requireUser(cur)
	if caller != admin {
		panic("nft: not admin")
	}
	if fees <= 0 {
		panic("nft: no fees")
	}
	amt := fees
	fees = 0
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bk.SendCoins(self, admin, chain.Coins{{Denom: nativeDenom, Amount: amt}})
	chain.Emit("WithdrawFees", "amount", strconv.FormatInt(amt, 10))
}

func ListOpen() string {
	out := ""
	n := 0
	items.Iterate("", "", func(_ string, value any) bool {
		it := value.(*item)
		if !it.listed {
			return false
		}
		if n >= 50 {
			return true
		}
		if out != "" {
			out += "\n"
		}
		out += ItemLine(it.id)
		n++
		return false
	})
	return out
}

func ProtocolBps() int64 {
	return protocolBps
}

func ProtocolFees() int64 {
	return fees
}

func Render(path string) string {
	_ = path
	out := "# Bazaar NFT\n\nMint a unique item, list it at a fixed GNOT price, or buy an open listing.\n\n"
	out += "- items: " + strconv.Itoa(nextID) + "\n"
	out += "- protocol fee: " + strconv.FormatInt(protocolBps, 10) + " bps\n\n"
	open := ListOpen()
	if open == "" {
		out += "_No open listings._\n"
	} else {
		out += "```\n" + open + "\n```\n"
	}
	return out
}

