	acts.ReverseIterate("", "", func(_ string, value any) bool {
		a := value.(*act)
		if !saleTapeKind(a) {
			return false
		}
		if slug != "" && a.slug != slug {
			return false
		}
		if byID && a.id != id {
			return false
		}
		if n >= 50 {
			return true
		}
		if out != "" {
			out += "\n"
		}
		out += a.kind + "|" + strconv.Itoa(a.id) + "|" + strconv.FormatInt(a.price, 10) + "|" + a.name
		n++
		return false
	})
	return out
}

